import java.util.*;
import java.lang.*;

class Solution {

    public List<Integer> sortOddDesc(List<Integer> l) {
        // List to store odd indexed values
        List<Integer> oddIdxValues = new ArrayList<>(l.size()/2);

        // Extract odd indexed values
        for(int i=1; i<l.size(); i+=2) {
            oddIdxValues.add(l.get(i));
        }

        // Sort the odd indexed values in descending order
        Collections.sort(oddIdxValues, Collections.reverseOrder());

        // List to store the rearranged list
        List<Integer> rearrangedList = new ArrayList<>(l.size());

        // Merge the even indexed values from original list with sorted odd indexed values
        int j = 0; // To iterate through oddIdxValues
        for(int i=0; i<l.size(); i++) {
            if(i % 2 == 0){
                // Add even indexed values from original list
                rearrangedList.add(l.get(i));
            } else {
                // Add sorted odd indexed values
                rearrangedList.add(oddIdxValues.get(j));
                j++;
            }
        }
        return rearrangedList; 
    }
}
